import Foundation

/// Loads JSON reference fixtures generated by the scripts in `tools/reference/`.
enum Fixture {
    enum LoadError: Error { case missing(String) }

    static func load<T: Decodable>(_ name: String, as type: T.Type = T.self) throws -> T {
        guard let url = Bundle.module.url(forResource: name, withExtension: "json", subdirectory: "Fixtures") else {
            throw LoadError.missing(name)
        }
        return try JSONDecoder().decode(T.self, from: Data(contentsOf: url))
    }
}

/// Relative comparison used throughout the physics tests. `scale` guards against tiny reference values.
func approxEqual(_ x: Double, _ y: Double, relative: Double, scale: Double = 0) -> Bool {
    abs(x - y) <= relative * max(abs(y), abs(x), scale)
}
